import React, { useEffect } from "react";
import { Route, Routes } from "react-router-dom";
import CryptoList from "./components/CryptoList";
import CryptoDetails from "./components/CryptoDetails";
import Register from "./components/Register";
import Login from "./components/Login";
import Dashboard from "./components/Dashboard";
import ModifierProfile from "./components/ModifierProfile";
import About from "./components/About";
import ForgotPassword from "./components/ForgotPassword";
import ResetPassword from "./components/ResetPassword";
import PageAlerts from "./components/PageAlerts";
import ProtectedRoutes from "./components/ProtectedRoutes";
import { AuthProvider } from "./components/AuthProvider";

const App = () => {
    return (
        <AuthProvider>
            <div>
                <Routes>
                    {/* Routes accessibles sans authentification */}
                    <Route path="/About" element={<About />} />
                    <Route path="/Register" element={<Register />} />
                    <Route path="/Login" element={<Login />} />
                    <Route path="Dashboard/:id" element={<Dashboard />} />
                    <Route path="/ModifierProfile/:id" element={<ModifierProfile />} />
                    <Route path="/PageAlerts/:id" element={<PageAlerts />} />
                    <Route path="/ForgotPassword" element={<ForgotPassword />} />
                    <Route path="/ResetPassword" element={<ResetPassword />} />
                    <Route path="/" element={<CryptoList />} />
                    <Route path="/cryptocurrencies/:id" element={<CryptoDetails />} />
                    <Route path="*" element={<div>Page non trouvée</div>} />

                    {/*/!* Routes protégées *!/*/}
                    {/*<Route*/}
                    {/*    path="/Dashboard/:id"*/}
                    {/*    element={*/}
                    {/*        <ProtectedRoutes>*/}
                    {/*            <Dashboard />*/}
                    {/*        </ProtectedRoutes>*/}
                    {/*    }*/}
                    {/*/>*/}
                    {/*<Route*/}
                    {/*    path="/ModifierProfil/:id"*/}
                    {/*    element={*/}
                    {/*        <ProtectedRoutes>*/}
                    {/*            <ModifierProfil />*/}
                    {/*        </ProtectedRoutes>*/}
                    {/*    }*/}
                    {/*/>*/}
                    {/*<Route*/}
                    {/*    path="/PageAlerts/:id"*/}
                    {/*    element={*/}
                    {/*        <ProtectedRoutes>*/}
                    {/*            <PageAlerts />*/}
                    {/*        </ProtectedRoutes>*/}
                    {/*    }*/}
                    {/*/>*/}
                </Routes>
            </div>
        </AuthProvider>
    );
};

export default App;
